import{_ as s,o as i,c as t,a4 as a}from"./chunks/framework.BE47AOxC.js";const h=JSON.parse('{"title":"Installation guidée","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"Installation guidée","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"installer/guide-pas-a-pas.md","filePath":"installer/guide-pas-a-pas.md"}'),n={name:"installer/guide-pas-a-pas.md"};function o(l,e,r,d,c,u){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="installation-guidée" tabindex="-1">Installation guidée <a class="header-anchor" href="#installation-guidée" aria-label="Permalink to &quot;Installation guidée {#installation-guidée}&quot;">​</a></h1><p>Il vous faut un serveur <strong>Debian 12, Ubuntu 22.04 ou Ubuntu 24.04</strong> (amd64 ou arm64 ; 2 Go de mémoire au minimum, 4 Go conseillés ; 20 Go de disque libre), un accès administrateur (<code>sudo</code>), et un nom <code>cms.&lt;votre domaine&gt;</code> qui <strong>pointe déjà</strong> sur ce serveur (enregistrement DNS A, et AAAA s&#39;il a de l&#39;IPv6). Pour le profil « Blog et presse », qui installe aussi le site public, un second nom, <code>www.&lt;votre domaine&gt;</code> (ou tout autre nom choisi pour le site) ; pour le profil « Sur mesure », un second nom, <code>api.&lt;votre domaine&gt;</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 1. Télécharger l&#39;installateur de la version voulue, et sa somme de contrôle</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">curl</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -fsSLO</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> https://github.com/Bastien-OC20/teuthis-cms-distribution/releases/download/vX.Y.Z/installer.sh</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">curl</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -fsSLO</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> https://github.com/Bastien-OC20/teuthis-cms-distribution/releases/download/vX.Y.Z/installer.sh.sha256</span></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 2. Vérifier que le fichier est intact : doit afficher « installer.sh: OK »</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sha256sum</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -c</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> installer.sh.sha256</span></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 3. Installer</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sudo</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> sh</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> installer.sh</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> --profil</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> collectivite</span></span></code></pre></div><p>Remplacez <code>vX.Y.Z</code> par la version choisie (page <em>Releases</em> du dépôt, dont les notes rappellent aussi la somme de l&#39;installateur) et <code>collectivite</code> par votre profil : <code>collectivite</code>, <code>blog_presse</code>, <code>portfolio</code>, <code>catalogue_devis</code> ou <code>sur_mesure</code>. Sans <code>--profil</code>, l&#39;installateur pose la question. <code>sh installer.sh --aide</code> liste toutes les options.</p><h2 id="ce-quil-vérifie-avant-de-rien-modifier" tabindex="-1">Ce qu&#39;il vérifie, avant de rien modifier <a class="header-anchor" href="#ce-quil-vérifie-avant-de-rien-modifier" aria-label="Permalink to &quot;Ce qu&#39;il vérifie, avant de rien modifier {#ce-quil-vérifie-avant-de-rien-modifier}&quot;">​</a></h2><ul><li><strong>Le système</strong> (Debian 12, Ubuntu 22.04 ou 24.04) et <strong>l&#39;architecture</strong> (amd64, arm64). Ailleurs, il refuse en expliquant pourquoi.</li><li><strong>La mémoire</strong> (refus sous 2 Go, avertissement sous 4 Go) et <strong>le disque</strong> (20 Go libres là où ira <code>/opt/teuthis</code>).</li><li><strong>Les ports 80 et 443</strong> : libres, sinon il nomme le programme qui les occupe.</li><li><strong>Le DNS</strong> : chaque nom à servir se résout, et vers une adresse de ce serveur. Il ne demande pour cela rien à aucun service extérieur : il compare la réponse du résolveur du serveur aux adresses de ses propres interfaces. Si votre hébergeur place le serveur derrière une traduction d&#39;adresses (NAT, IP publique « flottante »), l&#39;adresse publique n&#39;apparaît pas sur le serveur : l&#39;installateur l&#39;explique et vous demande de confirmer.</li></ul><h2 id="ce-quil-vous-demande" tabindex="-1">Ce qu&#39;il vous demande <a class="header-anchor" href="#ce-quil-vous-demande" aria-label="Permalink to &quot;Ce qu&#39;il vous demande {#ce-quil-vous-demande}&quot;">​</a></h2><p>Seulement ce que les options n&#39;ont pas déjà donné :</p><ul><li><strong>le profil</strong>, dans une liste qui dit aussi ce que chacun ne fait pas : « Catalogue et devis » n&#39;a ni panier, ni paiement, ni commande ; « Blog et presse » n&#39;a pas de commentaires ; « Sur mesure » ne livre aucun site public et s&#39;adresse à qui a un développeur ;</li><li><strong>le nom du back-office</strong> (<code>cms.…</code>) ; pour « Blog et presse », <strong>celui du site public</strong> (<code>www.…</code> proposé par défaut, option <code>--domaine-site</code>) ; pour « Sur mesure » ou avec <code>--api-publique</code>, <strong>celui de l&#39;API</strong> (<code>api.…</code>) ;</li><li><strong>une adresse de courriel</strong> : contact de Let&#39;s Encrypt et expéditeur des courriels ;</li><li><strong>le relais de messagerie</strong> (SMTP), qu&#39;on peut sauter : sans lui, aucun courriel ne part, et les demandes déposées restent visibles au guichet du back-office ;</li><li>s&#39;il y a lieu : <strong>installer Docker</strong> (depuis son dépôt apt officiel), activer <strong>le pare-feu</strong> <code>ufw</code> (SSH, 80 et 443 seulement, sans jamais couper votre session SSH) et <strong>les mises à jour de sécurité automatiques</strong> du système. Ces deux derniers sont proposés, jamais imposés.</li></ul><p>Un récapitulatif s&#39;affiche ensuite : rien n&#39;est modifié avant votre accord.</p><h2 id="ce-quil-fait" tabindex="-1">Ce qu&#39;il fait <a class="header-anchor" href="#ce-quil-fait" aria-label="Permalink to &quot;Ce qu&#39;il fait {#ce-quil-fait}&quot;">​</a></h2><p>Il installe Docker si besoin, télécharge la pile de cette version depuis la release GitHub (<code>teuthis-deploy-X.Y.Z.tar.gz</code>, dont il vérifie la somme), écrit <code>/opt/teuthis/.env</code> en mode 600 avec <strong>tous les secrets générés</strong> (mot de passe de la base, clé du captcha Altcha, identifiant de l&#39;organisation), active les gabarits Caddy, télécharge les images, démarre la pile, attend qu&#39;elle soit saine, puis vérifie qu&#39;elle répond <strong>en HTTPS</strong> — sous <code>cms.</code> et, pour « Blog et presse », sous <code>www.</code>. Il garde un journal dans <code>/var/log/teuthis-installation.log</code>, sans aucun secret.</p><h2 id="lauthenticité-des-images" tabindex="-1">L&#39;authenticité des images <a class="header-anchor" href="#lauthenticité-des-images" aria-label="Permalink to &quot;L&#39;authenticité des images {#lauthenticité-des-images}&quot;">​</a></h2><p>L&#39;archive de la pile porte l&#39;empreinte (<code>sha256:…</code>) de chaque image Teuthis publiée (<code>images-publiees.txt</code>). L&#39;installateur refuse une image téléchargée qui n&#39;a pas cette empreinte, toujours (<a href="/teuthis-cms-distribution/developpeurs/adr/0057-authenticite-des-images-a-l-installation">ADR-0057</a>).</p><p><strong>Si <code>cosign</code> est installé sur le serveur</strong>, il vérifie en plus la <strong>signature</strong> de chaque image : elle doit venir du workflow de publication de ce dépôt, pour cette version exacte. En cas d&#39;échec, l&#39;installation s&#39;arrête avant tout démarrage. <strong>Sans cosign, ou avec un cosign antérieur à la v3</strong> (les images sont signées au format de cosign v3, que les versions précédentes ne lisent pas), un avertissement vous le dit et l&#39;installation continue : l&#39;empreinte est vérifiée, pas l&#39;origine de l&#39;image. Pour l&#39;activer, installez cosign v3 ou plus récent avant de lancer l&#39;installateur (<a href="https://docs.sigstore.dev/cosign/system_config/installation/" target="_blank" rel="noreferrer">instructions</a>, par exemple le paquet <code>.deb</code> des <a href="https://github.com/sigstore/cosign/releases" target="_blank" rel="noreferrer">releases de cosign</a>). L&#39;installateur ne l&#39;installe jamais à votre place.</p><h2 id="ce-quil-affiche-à-la-fin" tabindex="-1">Ce qu&#39;il affiche à la fin <a class="header-anchor" href="#ce-quil-affiche-à-la-fin" aria-label="Permalink to &quot;Ce qu&#39;il affiche à la fin {#ce-quil-affiche-à-la-fin}&quot;">​</a></h2><ul><li><p><strong>L&#39;adresse de l&#39;écran d&#39;installation</strong> : <code>https://cms.&lt;votre domaine&gt;/installation?profil=&lt;votre profil&gt;</code>, où vous créez le compte administrateur et confirmez le profil. Pour « Blog et presse », saisissez-y aussi le nom du site public dans <strong>« Domaine du site public »</strong> : c&#39;est par lui que l&#39;API reconnaît le site, et le site affiche « site inconnu » tant qu&#39;il n&#39;est pas déclaré.</p></li><li><p><strong>La clé d&#39;installation</strong>, à part — jamais dans l&#39;adresse. Elle n&#39;est affichée qu&#39;une fois : copiez-la. Perdue, elle ne se retrouve pas, elle se réémet (l&#39;ancienne devient alors invalide) :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;">cd</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> /opt/teuthis</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;"> &amp;&amp; </span><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sudo</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> docker</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> compose</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> exec</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -T</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> cms-api</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> python</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -m</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> app.cli.installation_key</span></span></code></pre></div><p>La commande <code>teuthis cle-installation</code> la remplacera au prochain lot.</p></li></ul><h2 id="le-site-public-selon-le-profil" tabindex="-1">Le site public, selon le profil <a class="header-anchor" href="#le-site-public-selon-le-profil" aria-label="Permalink to &quot;Le site public, selon le profil {#le-site-public-selon-le-profil}&quot;">​</a></h2><p>Le site public est servi par le <strong>front de démarrage</strong> (<a href="/teuthis-cms-distribution/developpeurs/adr/0047-front-de-demarrage-optionnel">ADR-0047</a>), un thème par profil d&#39;usage, livrés l&#39;un après l&#39;autre :</p><table tabindex="0"><thead><tr><th>Profil</th><th>Site public</th></tr></thead><tbody><tr><td>Blog et presse</td><td><strong>Oui</strong>, thème « Blog et presse », sur <code>www.&lt;votre domaine&gt;</code> (affiché à la fin : « Site public : https://… »).</td></tr><tr><td>Collectivité, Portfolio, Catalogue et devis</td><td><strong>Pas encore</strong> : le thème est prévu, pas encore livré. Le back-office est prêt ; le site se branchera sur la même instance.</td></tr><tr><td>Sur mesure (headless)</td><td><strong>Aucun</strong>, par construction : le front de votre prestataire consomme l&#39;API, sur <code>api.&lt;votre domaine&gt;</code>.</td></tr></tbody></table><p>Pour « Blog et presse », l&#39;installateur active le gabarit Caddy <code>www.caddy</code> et écrit dans <code>.env</code> <code>TEUTHIS_DOMAINE_SITE</code>, <code>TEUTHIS_THEME_FRONT=blog-presse</code> et <strong><code>COMPOSE_PROFILES=front</code></strong> : c&#39;est ce profil Compose qui démarre le service <code>cms-front</code>. <code>docker compose</code> le lit dans <code>.env</code>, si bien que <code>docker compose up -d</code>, <code>pull</code>, <code>ps</code> ou <code>logs</code> en tiennent compte sans option. L&#39;image du front (<code>teuthis-front</code>) est vérifiée comme les autres (empreinte, et signature si <code>cosign</code> est présent) ; pour les autres profils, elle n&#39;est ni téléchargée ni vérifiée.</p><h2 id="le-relancer" tabindex="-1">Le relancer <a class="header-anchor" href="#le-relancer" aria-label="Permalink to &quot;Le relancer {#le-relancer}&quot;">​</a></h2><p>Relancer la même commande ne casse rien, et c&#39;est ce qu&#39;il faut faire après un échec (DNS pas encore propagé, port occupé, coupure réseau) : corrigez ce que le message indique, puis relancez. Docker déjà installé est laissé tel quel ; le <code>.env</code> n&#39;est <strong>jamais écrasé</strong> — ses secrets et l&#39;identifiant de l&#39;organisation sont réutilisés, seules les valeurs manquantes s&#39;y ajoutent ; les gabarits déjà actifs ne changent pas ; la pile est redémarrée si besoin ; et aucune clé n&#39;est réémise si l&#39;organisation est déjà installée.</p><p>Une option qui contredit le <code>.env</code> existant (un autre domaine, une autre version) est refusée : l&#39;installateur n&#39;est pas l&#39;outil pour changer une installation. La mise à jour d&#39;une version à l&#39;autre sera <code>teuthis mettre-a-jour</code> ; en attendant, voir <a href="/teuthis-cms-distribution/documentation/referent/ce-qui-manque-encore#ce-qui-manque-encore">Ce qui manque encore</a>.</p><h2 id="sans-question--le-mode-non-interactif" tabindex="-1">Sans question : le mode non interactif <a class="header-anchor" href="#sans-question--le-mode-non-interactif" aria-label="Permalink to &quot;Sans question : le mode non interactif {#sans-question--le-mode-non-interactif}&quot;">​</a></h2><p>Pour une installation scriptée, <code>--non-interactif</code> ne pose aucune question et refuse ce qui manque, en le nommant :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sudo</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> sh</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> installer.sh</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> --non-interactif</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> --installer-docker</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> --profil</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> blog_presse</span><span style="--shiki-light:#A0111F;--shiki-dark:#FF9492;"> \\</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;">  --domaine-cms</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> cms.monjournal.fr</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> --courriel</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> admin@monjournal.fr</span></span></code></pre></div><p>Chaque option a sa variable d&#39;environnement (<code>TEUTHIS_PROFIL</code>, <code>TEUTHIS_DOMAINE_CMS</code>…, liste dans <code>--aide</code>) ; le relais de messagerie se donne par <code>SMTP_HOST</code>, <code>SMTP_PORT</code>, <code>SMTP_SECURITY</code>, <code>SMTP_USERNAME</code> et <code>SMTP_PASSWORD</code>. Avec <code>sudo</code>, passez-les ainsi : <code>sudo SMTP_HOST=smtp.exemple.fr sh installer.sh …</code>.</p><blockquote><p><strong>Un secret passé par variable d&#39;environnement reste lisible pendant l&#39;installation.</strong> Tant que l&#39;installateur tourne, <code>root</code> (et le même utilisateur) peut lire son environnement de lancement dans <code>/proc/&lt;pid&gt;/environ</code> — <code>SMTP_PASSWORD</code> compris. L&#39;installateur retire <code>SMTP_USERNAME</code> et <code>SMTP_PASSWORD</code> de son environnement dès qu&#39;il les a lus : les commandes qu&#39;il lance (Docker, curl, apt) ne les héritent pas. Pour que le mot de passe ne passe par aucun environnement, répondez plutôt à la question (il ne s&#39;affiche pas), ou écrivez-le d&#39;avance dans <code>/opt/teuthis/.env</code> (mode 600) : l&#39;installateur le réutilise. Les autres secrets (base, captcha) sont générés et écrits directement dans le <code>.env</code>, jamais passés dans un environnement.</p><p>L&#39;installateur est écrit pour <code>sh</code> POSIX (dash) : il tourne en <code>set -eu</code>, <strong>sans <code>pipefail</code></strong>, que POSIX ne connaît pas. Là où l&#39;échec d&#39;une commande au milieu d&#39;un tube compte (somme SHA-256, empreinte de clé), il donne une sortie vide, que la comparaison qui suit refuse.</p></blockquote><p>Pour répéter une installation sans épuiser les limites de Let&#39;s Encrypt : <code>--tls essai</code>. Pour un essai sans nom de domaine réel : <code>--tls interne --sans-verification-dns</code> (certificat non reconnu des navigateurs, normal dans ce mode).</p>`,30)])])}const m=s(n,[["render",o]]);export{h as __pageData,m as default};
